                                  Date.parse('2026-10-11T12:10:00Z'), {});
        assert.equal(out.length, 1);
        assert.equal(out[0].id, 991234001);
        var noId = cz.placeholders([cr({ name: 'Quality gate', details_url: null,
                                         started_at: '2026-10-11T12:06:29Z' })],
