function classify(checkRuns, resolveRun, nowMs, opts) {
    var out = { zombies: [], live: 0, settled: 0, unresolvable: 0 };
    var staleMs = _num(opts, 'staleNoRunnerMinutes', DEFAULT_STALE_NO_RUNNER_MINUTES) * 60 * 1000;
