                     status: 'in_progress', conclusion: null,
                     started_at: '2026-10-11T18:33:45Z',
                     details_url: 'https://github.com/o/r/actions/runs/' + KICKER_RUN };
        if (extra) { for (var k in extra) { if (extra.hasOwnProperty(k)) base[k] = extra[k]; } }
        return base;
    }

