        assert.equal(out[0].name, 'Quality gate');
        assert.equal(out[0].runId, KICKER_RUN);
        assert.equal(out[0].id, 114566277295, 'the check-run id rides the entry (PATCH target)');
        assert.equal(out[0].reason, 'orphan-run-concluded');
